local function wallout(id,len,seed,vertical)local w,h=math.floor(len*128+.5),180;local im=Image(w,h,ColorMode.RGB);for y=0,h-1 do for x=0,w-1 do local seg=math.floor(x/490);local u=x%490;local sx=(seed*271+seg*733+(seg%2==0 and u or 490-u)*2.1)%1840+155;local sy=164+y/h*405;local p=sample(wall,sx,sy);im:drawPixel(x,y,p)end end;if vertical then local v=Image(h,w,ColorMode.RGB);for y=0,h-1 do for x=0,w-1 do v:drawPixel(h-y-1,x,im:getPixel(x,y))end end;im=v end;im:saveAs(root..'/runtime-PNG/'..id..'.png');table.insert(exports,{id=id,width=im.width,height=im.height,ppu=128,pivot={.5,.5}})end
