-- Four distinct native ground regions, no enlargement. 182x104 overlap gives 3136x1792, exactly 112px per world unit.
local function seam(old,im,ox,oy,vertical)
 local width=vertical and 182 or 104;local height=vertical and im.height or im.width;local back={};local prev={}
 for row=0,height-1 do local cur={};back[row]={};for col=4,width-5 do local x=vertical and col or row;local y=vertical and row or col;local a=old:getPixel(ox+x,oy+y);local b=im:getPixel(x,y);local cost=math.abs(pc.rgbaR(a)-pc.rgbaR(b))+math.abs(pc.rgbaG(a)-pc.rgbaG(b))+math.abs(pc.rgbaB(a)-pc.rgbaB(b));local best=0;local at=col;if row>0 then best=1e12;for j=math.max(4,col-2),math.min(width-5,col+2)do local v=prev[j]+math.abs(j-col)*1.5;if v<best then best=v;at=j end end end;cur[col]=cost+best;back[row][col]=at end;prev=cur end
 local at=4;for col=5,width-5 do if prev[col]<prev[at]then at=col end end;local out={};for row=height-1,0,-1 do out[row]=at;at=back[row][at]end;return out
end
local fs=sprite(3136,1792);local floors={open('floor-original'),open('floor-1'),open('floor-2'),open('floor-3')};for i,im in ipairs(floors)do local ix=(i-1)%2;local iy=math.floor((i-1)/2);local ox=ix*1477;local oy=iy*844;local old=merged(fs);local sv=ix==1 and seam(old,im,ox,oy,true)or nil;local sh=iy==1 and seam(old,im,ox,oy,false)or nil;local m=Image(im);for y=0,m.height-1 do for x=0,m.width-1 do local a=1;if sv then a=a*clamp((x-sv[y]+1)/2,0,1)end;if sh then a=a*clamp((y-sh[x]+1)/2,0,1)end;if a<1 then local p=m:getPixel(x,y);m:drawPixel(x,y,pix(pc.rgbaR(p),pc.rgbaG(p),pc.rgbaB(p),a*255))end end end;add(fs,'0'..i..'-painted-ground-region',m,Point(ox,oy))end
-- A separate finishing glaze calms high-frequency mineral flecks while keeping dark cracks crisp.
local base=merged(fs);local glaze=Image(fs.spec);local offsets={{0,0},{-5,0},{5,0},{0,-5},{0,5},{-4,-4},{4,4},{-4,4},{4,-4}}
for y=0,base.height-1 do for x=0,base.width-1 do local p=base:getPixel(x,y);local lum=(pc.rgbaR(p)+pc.rgbaG(p)+pc.rgbaB(p))/3;local r,g,b,n=0,0,0,0;for _,v in ipairs(offsets)do local q=base:getPixel(clamp(x+v[1],0,base.width-1),clamp(y+v[2],0,base.height-1));local l=(pc.rgbaR(q)+pc.rgbaG(q)+pc.rgbaB(q))/3;if math.abs(l-lum)<32 then r=r+pc.rgbaR(q);g=g+pc.rgbaG(q);b=b+pc.rgbaB(q);n=n+1 end end;glaze:drawPixel(x,y,pix(r/n*.82,g/n*.82,b/n*.82,215))end end;add(fs,'05-matte-material-finish',glaze)
